int gauss_legendre_max_points() noexcept { return kMaxPoints; }

void gauss_legendre_rule(int point_count, double nodes[], double weights[]) {
    if (point_count < 1 || point_count > kMaxPoints) {
        throw std::out_of_range("unsupported Gauss-Legendre point count");
    }
    if (nodes == nullptr || weights == nullptr) {
        throw std::invalid_argument("Gauss-Legendre output arrays must not be null");
    }
    const int offset = point_count * (point_count - 1) / 2;
    std::copy_n(kNodes.data() + offset, point_count, nodes);
    std::copy_n(kWeights.data() + offset, point_count, weights);
}
